import { CategoryCache, ShelfCategory } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function jsonEqual(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), message);
}

function expectRangeError(action: () => unknown, message: string): void {
  try {
    action();
  } catch (error) {
    assert(error instanceof RangeError, message);
    return;
  }
  throw new Error(message);
}

async function expectRejected(errorType: typeof RangeError | typeof TypeError, action: () => Promise<unknown>, message: string): Promise<void> {
  try {
    await action();
  } catch (error) {
    assert(error instanceof errorType, message);
    return;
  }
  throw new Error(message);
}

async function main(): Promise<void> {
  expectRangeError(() => new CategoryCache(async () => [], -1), 'negative freshness rejected');
  expectRangeError(() => new CategoryCache(async () => [], Number.NaN), 'NaN freshness rejected');
  expectRangeError(() => new CategoryCache(async () => [], Number.POSITIVE_INFINITY), 'infinite freshness rejected');

  const source: ShelfCategory[] = [
    { id: 2, name: ' Two ', note: 'n2' },
    { id: 2, name: 'Duplicate', note: 'n3' },
  ];
  let calls = 0;
  const cache = new CategoryCache(async () => {
    calls += 1;
    return source;
  }, 10);
  jsonEqual(cache.getCurrent(), [], 'initial current value is empty');
  const first = await cache.refresh(100);
  assert(calls === 1, 'initial refresh fetches once');
  jsonEqual(first, source, 'order, duplicate IDs, and text are preserved');
  first[0].name = 'caller mutation';
  source[0].name = 'fetcher mutation';
  source.push({ id: 3, name: 'Later', note: 'later' });
  jsonEqual(cache.getCurrent(), [
    { id: 2, name: ' Two ', note: 'n2' },
    { id: 2, name: 'Duplicate', note: 'n3' },
  ], 'cache does not alias fetched or returned data');

  const currentOne = cache.getCurrent();
  const currentTwo = cache.getCurrent();
  assert(currentOne !== currentTwo && currentOne[0] !== currentTwo[0], 'getCurrent returns fresh copies');
  const boundary = await cache.refresh(110);
  assert(calls === 1, 'freshness boundary is inclusive');
  assert(boundary !== currentOne && boundary[0] !== currentOne[0], 'cached refresh returns copies');
  await cache.refresh(111);
  assert(calls === 2, 'stale cache refetches');

  cache.invalidate();
  assert(cache.getCurrent().length === 3, 'invalidate does not erase current value');
  await cache.refresh(112);
  assert(calls === 3, 'invalidate forces next fetch');

  await expectRejected(RangeError, () => cache.refresh(Number.NaN), 'non-finite now rejects with RangeError');
  assert(calls === 3, 'invalid now does not invoke fetcher');

  let malformed = false;
  let validationCalls = 0;
  const validationCache = new CategoryCache(async () => {
    validationCalls += 1;
    if (malformed) return [{ id: 1.5, name: 'Bad', note: 'x' }] as readonly ShelfCategory[];
    return [{ id: 1, name: 'Good', note: 'ok' }];
  }, 0);
  await validationCache.refresh(1);
  malformed = true;
  await expectRejected(TypeError, () => validationCache.refresh(2), 'non-integer id rejects');
  jsonEqual(validationCache.getCurrent(), [{ id: 1, name: 'Good', note: 'ok' }], 'malformed result preserves prior cache');
  assert(validationCalls === 2, 'malformed fetch invoked once');

  const malformedValues: readonly ShelfCategory[][] = [
    [{ id: Number.POSITIVE_INFINITY, name: 'Bad', note: 'x' }],
    [{ id: 1, name: '   ', note: 'x' }],
    [{ id: 1, name: 'Good', note: 4 as unknown as string }],
  ];
  for (const value of malformedValues) {
    const badCache = new CategoryCache(async () => value, 0);
    await expectRejected(TypeError, () => badCache.refresh(0), 'each malformed field rejects with TypeError');
    jsonEqual(badCache.getCurrent(), [], 'rejected initial fetch leaves cache empty');
  }

  const fetchError = new Error('fetch failed');
  const preserving = new CategoryCache(async () => [{ id: 7, name: 'Seven', note: '' }], 0);
  await preserving.refresh(0);
  const failing = preserving as unknown as { refresh(nowMs: number): Promise<ShelfCategory[]> };
  void failing;
  let shouldFail = false;
  const rejectedCache = new CategoryCache(async () => {
    if (shouldFail) throw fetchError;
    return [{ id: 7, name: 'Seven', note: '' }];
  }, 0);
  await rejectedCache.refresh(0);
  shouldFail = true;
  try {
    await rejectedCache.refresh(1);
    throw new Error('fetch rejection should propagate');
  } catch (error) {
    assert(error === fetchError, 'original fetch rejection propagates');
  }
  jsonEqual(rejectedCache.getCurrent(), [{ id: 7, name: 'Seven', note: '' }], 'rejected fetch preserves prior state');

  let emptyCalls = 0;
  const emptyCache = new CategoryCache(async () => { emptyCalls += 1; return []; }, 5);
  jsonEqual(await emptyCache.refresh(10), [], 'empty fetched arrays are valid');
  await emptyCache.refresh(15);
  assert(emptyCalls === 1, 'successful empty array is cached');
}

main().catch((error: unknown) => { throw error; });

